NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Obadiah'

CHAPTERS = {
    1: {
        1: 'Gesicht Obadjahs. So spricht der Herr Jehovah zu Edom: Wir haben ein Gerücht gehört von Jehovah, und eine Gesandtschaft wird gesandt unter die Völkerschaften: Steht auf, und laßt uns aufstehen wider sie zum Streite.',
        2: 'Siehe, Ich mache dich klein unter den Völkerschaften. Sehr verachtet bist du.',
        3: 'Die Vermessenheit deines Herzens hat dich verführt, die du wohnst in den Klüften der Felsenklippen, der Höhe deines Sitzes. Er spricht in seinem Herzen: Wer wird mich zur Erde hinabstürzen?',
        4: 'Und wenn du wie der Adler in die Höhe führest und setztest dein Nest zwischen die Sterne, will Ich dich von da herabziehen, spricht Jehovah.',
        5: 'Wenn Diebe über dich kommen, wenn Verheerer der Nacht, wie wirst du da untergehen! Werden sie nicht stehlen, bis sie genug haben? Wenn Winzer über dich kommen, werden sie dir nicht eine Nachlese verbleiben lassen?',
        6: 'Wie wird Esau durchforscht, seine Schlupfwinkel durchsucht werden!',
        7: 'Bis zur Grenze geleiten dich alle Männer deines Bundes, die Männer, die in Frieden mit dir waren, verführen, sie überwältigen dich; dein Brot - sie legen unter dir einen Fallstrick; du aber merkst nicht darauf.',
        8: 'Wird es nicht, spricht Jehovah, an jenem Tage geschehen, daß Ich die Weisen aus Edom und die Einsicht aus dem Berge Esaus zerstöre?',
        9: 'Und entsetzt werden sein deine Helden, Theman, daß der Mann ausgerottet wird vom Berge Esaus ob dem Morden.',
        10: 'Ob der Gewalttat an deinem Bruder Jakob wirst du bedeckt mit Scham, und wirst ausgerottet werden in Ewigkeit,',
        11: 'Am Tage, da du gegenüber standest, am Tage, da Fremde seine Streitmacht gefangen führten, und Ausländer durch seine Tore einzogen und über Jerusalem das Los warfen, warst auch du wie einer von ihnen.',
        12: 'Du solltest nicht zusehen am Tage deines Bruders, am Tage der Entfremdung, und nicht froh sein über die Söhne Jehudahs am Tage ihrer Zerstörung, und nicht deinen Mund groß machen am Tage der Drangsal.',
        13: 'Nicht solltest du zum Tore Meines Volkes eingehen am Tage ihrer Not, du solltest nicht, auch du, sein Übel ansehen am Tage seiner Not; und nicht ausstrecken an sein Vermögen am Tage seiner Not.',
        14: 'Und solltest nicht stehen an der Wegscheide, seine Entkommenen auszurotten; und nicht sollst du seinen Rest überantworten am Tag der Drangsal.',
        15: 'Denn nahe ist Jehovahs Tag über alle Völkerschaften; wie du getan hast, so wird dir getan; deine Vergeltung kehrt auf dein Haupt zurück.',
        16: 'Denn wie ihr getrunken habt auf dem Berg Meiner Heiligkeit, so sollen alle Völkerschaften beständig trinken, und sie sollen trinken und hinabschlingen, und sollen sein, als wären sie nicht gewesen.',
        17: 'Aber auf dem Berge Zijons wird ein Entkommen sein, und wird sein eine Heiligkeit, und das Haus Jakob wird erblich besitzen ihren Erbbesitz.',
        18: 'Und das Haus Jakob wird ein Feuer und das Haus Joseph eine Flamme und das Haus Esaus zur Stoppel werden, und sie zünden sie an und fressen sie auf, daß Esaus Hause kein Rest überbleibt; denn Jehovah hat es geredet.',
        19: 'Und die vom Mittag nehmen ein den Berg Esaus, und die in der Niederung die Philister, und sie besitzen erblich das Feld Schomrons, und Benjamin das Gilead.',
        20: 'Und die Weggeführten dieser Streitmacht der Söhne Israels, so unter den Kanaanitern bis gen Zarpath sind, und die Weggeführten Jerusalems, die in Sepharad sind, werden die Städte im Mittag erblich besitzen.',
        21: 'Und Retter werden auf den Berg Zijon heraufziehen, zu richten den Berg Esaus, und Jehovahs wird sein das Königtum!',
    },
}
